function abc(x : number, y : number, z : number) : number {
    let r : number = 0

    for (let i : number = x; i <= z; i = i + 0.5) {
        r = (r * 10) + (y * z) 
    }

    return r
}

function fat(n : number) : number {
    let r : number = 1

    for (let i : number = 1; i <= n; i++) {
        r = r * i
    }

    return r
}
